 const [fetched,reportVisits]=await Promise.all([api(type==='payouts'?'reports/payments':type==='client_balance'?'clients':direct?type:'reports/'+type),['One-off jobs','Recurring jobs'].includes(name)?api('visits').catch(()=>null):Promise.resolve(null)]);
 if(version!==viewVersion)return '';resource='';let list=Array.isArray(fetched)?fetched:fetched.appointments||[];
 if(Array.isArray(reportVisits))cache.visits=reportVisits;
 if(name==='One-off jobs'||name==='Recurring jobs')list=list.filter(x=>x.job_type===(name==='One-off jobs'?'one_off':'recurring'));
