let reportChatThread=[],reportChatHistory=[],reportChatGeneration=0;
function openReportBuilder(){modal('Build Jobber Reporting Apps',`<section class="report-ai"><div class="actions"><details><summary>Recent chats</summary><button data-report-history="${Math.max(0,reportChatHistory.length-1)}">Recent conversation</button><button data-report-chat="all">View all chats</button></details><button data-report-chat="new">New chat</button><button data-close aria-label="Close Jobber AI panel">Close Jobber AI panel</button></div><div id="report-chat-log" aria-live="polite"></div><div class="report-prompts">${['Which reports improve decision-making?','Can you show monthly revenue?','How are sales trending?'].map(q=>`<button data-report-prompt="${esc(q)}">${esc(q)}</button>`).join('')}</div><label>Ask a question<textarea id="report-question" rows="4" placeholder="Ask a question"></textarea></label><button data-report-chat="send" class="primary">Send</button></section>`,true);drawReportChat();}
function drawReportChat(){const log=$('#report-chat-log');if(log)log.innerHTML=reportChatThread.map((r,i)=>`<article class="card"><h3>${esc(r.title)}</h3><p>${esc(r.text)}</p>${r.rows?genericTable(r.rows):''}${r.rows?`<div class="actions">${[['good','Good response'],['bad','Bad response'],['copy','Copy response'],['save','Save Report']].map(([key,label])=>`<button data-report-response="${key}" data-response-index="${i}" aria-pressed="${r.rating===key}">${label}</button>`).join('')}</div>`:''}</article>`).join('');}
async function askReportBuilder(question){const generation=++reportChatGeneration,version=panelVersion;const response={title:question,question,text:'Analyzing live workspace records…'};reportChatThread.push(response);drawReportChat();
 try{const [invoices,jobs,expenses,visits]=await Promise.all(['invoices','jobs','expenses','visits'].map(p=>api(p)));if(generation!==reportChatGeneration||version!==panelVersion)return;
 const q=question.toLowerCase(),groups=new Map(),add=(key,amount)=>groups.set(key,(groups.get(key)||0)+Number(amount||0)),issued=invoices.filter(r=>!['draft','void','bad_debt'].includes(r.status));
 if(q.includes('visit type')){for(const visit of visits){const job=jobs.find(j=>j.id===visit.job_id);add(visit.visit_type||job?.job_type||'Unspecified',visit.billable_amount_cents||0);}response.text='Visit billable revenue grouped by visit/job type. This is scheduled visit value, not collected payments.';}
 else if(q.includes('recurring')){for(const job of jobs.filter(j=>j.job_type==='recurring'))add(clients.find(c=>c.id===job.client_id)?.lead_source||'Unspecified',job.total_cents);response.text='Recurring contract value grouped by client lead source.';}
 else{for(const invoice of issued)add(String(invoice.issued_date||invoice.created_at||'Undated').slice(0,7),invoice.total_cents);if(q.includes('profit')||q.includes('loss'))for(const expense of expenses)add(String(expense.date_incurred||expense.created_at||'Undated').slice(0,7),-Number(expense.amount_cents||0));response.text=q.includes('profit')?'Monthly issued invoice value less recorded expenses.':q.includes('decision')?'Use monthly invoice revenue to track demand, aged receivables to prioritize collections, and job profitability to review costs. Here is monthly issued invoice revenue.':'Monthly issued invoice revenue from live workspace data. Draft, void and bad-debt invoices excluded.';}
 response.rows=[...groups].sort(([a],[b])=>a.localeCompare(b)).map(([group,value])=>({group,total_cents:value}));if(!response.rows.length)response.text+=' No matching records yet.';
 reportChatHistory.push({title:question,thread:reportChatThread.map(r=>({...r}))});drawReportChat();
 }catch(err){if(generation===reportChatGeneration&&version===panelVersion){response.text='Unable to load report data: '+err.message;drawReportChat();}}
}
function reportMapMarkup(){return `<section class="card"><h2>GPS Waypoints</h2><div class="actions">${['Map','Satellite','Zoom in','Zoom out','Street View Pegman','Fullscreen','Live GPS Tracking'].map(x=>`<button data-report-map="${x}">${x}</button>`).join('')}<label>Date<input type="date" data-report-map-date></label></div><div id="report-map" class="report-map" tabindex="0" aria-label="GPS Waypoints map"><button data-report-map="Fullscreen" class="map-exit">Toggle fullscreen</button>${reportMapPoints()}</div><p id="report-map-status">Map · Zoom 1</p></section>`;}
function reportMapPoints(date=''){const points=(rows||[]).filter(r=>(!date||String(r.created_at||r.start_at||'').startsWith(date))&&(r.lat??r.latitude)!=null&&(r.lng??r.longitude)!=null);return `<svg viewBox="0 0 720 360" aria-label="Recorded GPS coordinates">${points.map(r=>{const lat=Number(r.lat??r.latitude),lng=Number(r.lng??r.longitude);return Number.isFinite(lat)&&Number.isFinite(lng)?`<circle cx="${(lng+180)*2}" cy="${(90-lat)*2}" r="5"><title>${esc(r.name||r.title||'Waypoint')} ${lat}, ${lng}</title></circle>`:'';}).join('')}</svg>${points.length?'':'<p>No recorded GPS coordinates for this date.</p>'}`;}
