let authView = 'login', authSupportOpen = false, authSupportTab = 'Home';
function loginScreen(view = authView) {
 authView = view;
 if ($('#sidebar')) $('#sidebar').innerHTML = '';
 if ($('#onboarding')) $('#onboarding').hidden = true;
 if ($('#workspace')?.style) $('#workspace').style.marginLeft = '0';
 const forgot = view === 'forgot', signup = view === 'signup';
 $('#workspace').innerHTML = `<section class="portal auth-screen"><h1>${forgot ? 'Forgot Your Password' : signup ? 'Sign Up' : 'Log in to Jobber'}</h1>
   <form id="auth-screen-form">${field('Email Address', 'email', '', 'email')}
     ${forgot ? '' : field('Password', 'password', '', 'password')
       + '<button type="button" data-show-password aria-pressed="false">Show Password</button>'}
     <div class="form-error"></div><p id="auth-result" role="status"></p>
     <button type="submit" class="primary">${forgot || signup ? 'Continue' : 'Log In'}</button></form>
   ${forgot ? '' : `<div class="auth-sso">${(signup ? ['Google', 'Apple'] : ['Google', 'Intuit', 'Apple'])
     .map(provider => `<button type="button" data-auth-sso="${provider}">Continue with ${provider}</button>`).join('')}</div>`}
   ${forgot ? '<a href="/login" data-auth-view="login">Back to Login</a>' : signup
     ? '<a href="/login" data-auth-view="login">Log In</a>'
     : '<a href="/login?view=forgot" data-auth-view="forgot">Forgot Password</a> · '
       + '<a href="/login?view=signup" data-auth-view="signup">Sign Up</a>'}
   <button type="button" data-auth-chat>Chat</button><div id="auth-support"></div></section>`;
 const form = $('#auth-screen-form');
 form?.querySelectorAll?.('input')?.forEach(input => input.required = true);
 form.onsubmit = async event => {
   event.preventDefault();
   const data = Object.fromEntries(new FormData(form));
   try {
     if (forgot) {
       $('#auth-result').textContent = 'Sandbox reset requested for ' + data.email + '. No email is sent in this sandbox.';
       return;
     }
     const result = signup ? await api('auth/bootstrap', 'POST', {}) : await api('auth/login', 'POST', data);
     sessionStorage.setItem('token', result.token);
     location.href = '/home';
   } catch (err) { error(err); }
 };
 $('#workspace').onclick = async event => {
   const button = event.target.closest('[data-auth-view],[data-auth-sso],[data-show-password],[data-auth-chat],[data-auth-tab],[data-auth-close]');
   if (!button) return;
   event.preventDefault();
   try {
     if (button.dataset.authView) return loginScreen(button.dataset.authView);
     if (button.dataset.authSso) {
       button.disabled = true;
       const result = await api('auth/bootstrap', 'POST', {});
       sessionStorage.setItem('token', result.token);
       location.href = '/home';
     }
     if (button.hasAttribute('data-show-password')) {
       const input = form.querySelector('[name="password"]');
       const show = input.type === 'password';
       input.type = show ? 'text' : 'password';
       button.textContent = show ? 'Hide Password' : 'Show Password';
       button.setAttribute('aria-pressed', String(show));
     }
     if (button.hasAttribute('data-auth-chat')) authSupportOpen = true;
     if (button.hasAttribute('data-auth-close')) authSupportOpen = false;
     if (button.dataset.authTab) authSupportTab = button.dataset.authTab;
     renderAuthSupport();
   } catch (err) { button.disabled = false; error(err); }
 };
 renderAuthSupport();
}
function renderAuthSupport() {
 const container = $('#auth-support');
 if (!container) return;
 container.innerHTML = authSupportOpen ? `<aside class="card auth-support" aria-label="Authentication support">
   <button type="button" data-auth-close>Close</button><nav class="tabs">${['Home', 'Messages', 'News'].map(tab =>
     `<button type="button" data-auth-tab="${tab}" aria-pressed="${authSupportTab === tab}">${tab}</button>`).join('')}</nav>
   <h2>${authSupportTab === 'Messages' ? 'How can we help?' : authSupportTab === 'News' ? 'Product news' : 'Welcome to Jobber'}</h2>
   ${authSupportTab === 'Messages' ? '<p>For sign-in help, open Forgot Password or contact the support team.</p>'
     + '<a href="mailto:support@getjobber.com">Email Support</a>' : ''}
   <article class="card"><h3>New: Business Analysis Assistant</h3><p>Explore revenue, invoices, and upcoming work after signing in.</p></article>
   ${helpArticles.slice(0, 3).map(([name, , copy]) => `<details><summary>${name}</summary><p>${copy}</p></details>`).join('')}
   <details><summary>Product integrations</summary><p>Connect accounting, photos, and communication tools from Apps.</p></details>
   </aside>` : '';
}

function withRouteHrefs(html) {
 return html.replace(/<a\b([^>]*\bdata-go="([^"]+)"[^>]*)>/g, (tag, attributes, path) => {
   if (/\bhref=/.test(attributes)) return tag;
   return `<a href="/${path.replaceAll(' ', '%20')}"${attributes}>`;
 });
}

function preferenceValue(preferences, name) {
 const raw = (Array.isArray(preferences) ? preferences : []).find(item => item.name === name)?.value_json;
 try { return typeof raw === 'string' ? JSON.parse(raw) || {} : raw || {}; }
 catch { return {}; }
}

const onboardingSteps = [
 ['Branding', 'settings/business-profile', 'Add your logo, brand colors, and business details to personalize client documents.'],
 ['Create Client', 'clients', 'Add a client and their contact information, then create a service property.', 'clients'],
 ['Create Quote', 'quotes', 'Choose a client and add products or services to prepare your first quote.', 'quotes'],
 ['Schedule Visit', 'schedule', 'Choose a time on the calendar, select a job, and assign your team.'],
 ['Jobber Payments', 'settings/jobber-payments', 'Review payment methods and enable payments for your workspace.'],
 ['Mobile App / Team', 'settings/manage-team', 'Add your team members and use the mobile workspace to manage work on site.']
];
function onboardingMarkup(preferences = []) {
 return `<section class="card home-onboarding"><h2>Get set up quickly</h2><p>6 steps · About 11 minutes</p>
   ${onboardingSteps.map(([label, path, guidance, create], index) => {
     const complete = preferenceValue(preferences, 'onboarding-step-' + index).enabled;
     return `<details class="onboarding-step"><summary>${complete ? '✓ ' : ''}${label}</summary>
       <p>${guidance}</p><a href="/${path}" data-go="${path}">Open ${label}</a>
       ${create ? `<button data-create="${create}">${label}</button>` : ''}
       <label class="toggle-row">Completed<input type="checkbox" data-preference="onboarding-step-${index}"
         ${complete ? 'checked' : ''}></label></details>`;
   }).join('')}</section>`;
}
async function onboarding() {
 const version = ++panelVersion;
 const preferences = await safePrefs();
 if (version !== panelVersion) return;
 modal('Get set up quickly', onboardingMarkup(preferences), true);
}

const feedCategories = [
 'Quotes viewed', 'Quotes approved', 'Changes requested on quotes', 'Online booking created',
 'New request submitted', 'Visit reminders', 'Job completed', 'Invoice viewed', 'Payment received',
 'Payout deposited', 'Client text message reply', 'Team mentions in notes', 'Receptionist call summary'
];
let feedSettings = {};
function notificationCategory(notification) {
 const text = [notification.category, notification.event_type, notification.type, notification.title]
   .filter(Boolean).join(' ').toLowerCase().replaceAll('_', ' ');
 const patterns = [
 /quote.*view/, /quote.*approv/, /chang.*request/, /booking/, /request.*submit|new request/,
 /visit.*remind/, /job.*complet/, /invoice.*view/, /payment.*receiv/, /payout/,
 /text.*reply|sms|message.*reply/, /mention/, /receptionist|call summary/
 ];
 return feedCategories[patterns.findIndex(pattern => pattern.test(text))] || '';
}
function filterNotificationFeed() {
 document.querySelectorAll('[data-feed-category]').forEach(row => {
   row.hidden = feedSettings[row.dataset.feedCategory] === false;
 });
}
async function customizeFeed() {
 const container = $('#feed-customization');
 if (!container) return;
 if (!container.hidden) { container.hidden = true; return; }
 const version = panelVersion;
 const preferences = await safePrefs();
 if (version !== panelVersion) return;
 feedSettings = preferenceValue(preferences, 'notification_feed_settings');
 container.innerHTML = '<h3>Customize Feed</h3>' + feedCategories.map(category => `
   <label class="toggle-row">${category}<input type="checkbox" role="switch" data-feed-switch="${category}"
     ${feedSettings[category] !== false ? 'checked' : ''}></label>`).join('');
 container.hidden = false;
 filterNotificationFeed();
 let saving = Promise.resolve();
 container.onchange = event => {
   const input = event.target;
   if (!input.dataset.feedSwitch) return;
   feedSettings[input.dataset.feedSwitch] = input.checked;
   filterNotificationFeed();
   const snapshot = {...feedSettings};
   saving = saving.then(() => savePreference('notification_feed_settings', snapshot)).catch(error);
 };
}

