function batchAction(target) {
 if (target.dataset.action === 'more') { moduleMoreActions(); return Promise.resolve(true); }
 if (target.dataset.action === 'share-request' || target.dataset.action === 'share-booking') {const url=location.origin+'/booking';modal('Share or Embed',field('Public request URL','public_url',url)+`<button data-action="copy-booking">Copy Link</button><label>Embed code<textarea readonly>${esc('<iframe src="'+url+'" title="Request a service"></iframe>')}</textarea></label>`);return Promise.resolve(true);}
 if (target.dataset.action === 'signature-details') {modal('Signature & Client Approval Details','<p>Send a quote to your client to collect approval and a signature. Approved quotes can be converted into jobs.</p>'+btn('Manage integrations','settings/integrations'));return Promise.resolve(true);}
 if (target.dataset.action === 'bookkeeping-walkthrough') {modal('Watch how it works','<ol><li>Sync QuickBooks to bring transactions into your ledger.</li><li>Review expense categories in Reconciliation.</li><li>Compare income and expenses before closing the month.</li></ol>');return Promise.resolve(true);}
 if (target.dataset.action === 'find-time') return findTimeComposer();
 if (target.dataset.action === 'merge-clients') return mergeClientsWizard();
 if (target.hasAttribute('data-open-profile')) return profilePanel();
 if (target.hasAttribute('data-customize-feed')) return customizeFeed();
 if (target.dataset.helpView) return helpPanel(target.dataset.helpView);
 if (target.dataset.updatesPage) return productUpdatesPanel(Number(target.dataset.updatesPage));
 if (target.dataset.labsFeedback) return actionForm('Give Feedback', field('Feedback', 'feedback', '', 'text', true),
   data => savePreference('labs-feedback-' + Date.now(), {...data, experiment: target.dataset.labsFeedback}));
 if (target.hasAttribute('data-ai-new-chat')) {
   ++aiGeneration; aiThread = []; renderAssistantThread(); return Promise.resolve(true);
 }
 if (target.dataset.aiPrompt) return askAssistant(target.dataset.aiPrompt);
 if (target.hasAttribute('data-home-mkt-more')) {
   const menu = $('#home-marketing-menu');
   menu.hidden = !menu.hidden;
   target.setAttribute('aria-expanded', String(!menu.hidden));
   return Promise.resolve(true);
 }
 if (target.hasAttribute('data-home-mkt-dismiss')) return (async () => {
   const card = target.closest('.home-marketing');
   card.hidden = true;
   try {
     if (await savePreference('home-marketing', {dismissed: true}) === false) card.hidden = false;
   } catch (err) { card.hidden = false; throw err; }
 })();
 if (target.dataset.gapAction) return gapAction(target.dataset.gapAction);
 return false;
}

