async function saveClientExtras(clientId,data,primaryPropertyId){
 const prefixes=['property_',...Object.keys(data).filter(k=>/^property_\d+_street1$/.test(k)).map(k=>k.replace('street1',''))];
 for(const prefix of prefixes){if(!data[prefix+'street1'])continue;const propPayload={is_primary:prefix==='property_'?1:0,tax_rate:prefix==='property_'?Number(data.property_tax_rate||0):0,...Object.fromEntries(['street1','street2','city','state','postal_code','country'].map(k=>[k,data[prefix+k]||'']))};if(prefix==='property_'&&primaryPropertyId)await api('properties/'+primaryPropertyId,'PATCH',propPayload);else await api('properties','POST',{client_id:clientId,...propPayload});}
 for(const key of Object.keys(data).filter(k=>/^contact_\d+_first_name$/.test(k))){const prefix=key.replace('first_name','');if(data[key]||data[prefix+'last_name']||data[prefix+'email']||data[prefix+'phone'])await api('contacts','POST',{client_id:clientId,name:[data[prefix+'title'],data[prefix+'first_name'],data[prefix+'last_name']].filter(Boolean).join(' ').trim(),role_title:data[prefix+'role']||'',phone:data[prefix+'phone']||'',email:data[prefix+'email']||'',is_primary:data[prefix+'billing']?1:0});}
 const extra=Object.fromEntries(Object.entries(data).filter(([key])=>key.startsWith('extra_')));if(Object.keys(extra).length)await savePreference('client-extra-channels-'+clientId,extra);
}

function availableScheduleSlots(appointments, date, duration, assigned = []) {
 return [8,10,13,15].map(hour => {
   const start = new Date(`${date}T${String(hour).padStart(2,'0')}:00:00`), end = new Date(+start + duration * 60000);
   const busy = appointments.some(a => {
     let ids = a.assigned_user_ids_json || []; if (typeof ids === 'string') { try { ids = JSON.parse(ids); } catch { ids = []; } }
     return (!assigned.length || !ids.length || assigned.some(id => ids.map(Number).includes(Number(id))))
       && a.status !== 'cancelled' && Date.parse(a.start_at || a.scheduled_start) < +end && Date.parse(a.end_at || a.scheduled_end) > +start;
   });
   return {hour, start, end, busy};
 });
}
async function findTimeComposer() {
 const version = ++panelVersion;
 const scheduleData = await api('schedule');
 if (version !== panelVersion) return;
 modal('Find a Time', `<form id="find-time-form"><div class="tabs">${['Job','Request','Task','Event'].map((name,i)=>`<label><input type="radio" name="item_type" value="${name}" ${i?'':'checked'}>${name}</label>`).join('')}</div><div class="form-grid">${select('Client','client_id',clients.map(c=>[c.id,c.display_name]))}${field('Title','title')}${select('Duration','duration',[[30,'30 min'],[60,'1 hr'],[120,'2 hr'],[240,'4 hr']],60)}${field('Date','date',todayIso(),'date')}</div><fieldset><legend>Assign to</legend>${team.map(t=>`<label><input type="checkbox" name="assigned" value="${t.id}">${esc(t.name)}</label>`).join('')}</fieldset><div id="available-slots" class="actions"></div><p class="form-error"></p><button class="primary" type="submit">Schedule</button><button type="button" id="find-more-options">More Options</button></form>`,true,true);
 const form = $('#find-time-form'); if (!form?.querySelector) return;
 let chosen = null;
 const refresh = () => {
   const data = new FormData(form), assigned = data.getAll('assigned'); chosen = null;
   const slots = availableScheduleSlots(scheduleData.appointments || [], data.get('date'), Number(data.get('duration')), assigned);
   const slotPanel=$('#available-slots');if(!slotPanel)return;
   slotPanel.innerHTML = slots.map(s=>`<button type="button" data-time-hour="${s.hour}" ${s.busy?'disabled':''}>${s.hour%12||12}:00 ${s.hour>=12?'PM':'AM'}${s.busy?' · Unavailable':''}</button>`).join('');
   $('#available-slots').onclick = event => {const button=event.target.closest('[data-time-hour]');if(!button||button.disabled)return;chosen=slots.find(s=>s.hour===Number(button.dataset.timeHour));$('#available-slots')?.querySelectorAll?.('button')?.forEach(b=>b.setAttribute('aria-pressed',String(b===button)));};
 };
 form.onchange = refresh; refresh();
 const moreOptions=$('#find-more-options');if(moreOptions)moreOptions.onclick = () => builder(({Job:'jobs',Request:'requests',Task:'tasks',Event:'tasks'})[new FormData(form).get('item_type')]);
 form.onsubmit = async event => {event.preventDefault();try {
   if(!chosen)throw Error('Select an available time');const data=new FormData(form),name=String(data.get('title')||'').trim();if(!name)throw Error('Enter a title');
   const timing={scheduled_start:chosen.start.toISOString(),scheduled_end:chosen.end.toISOString(),assigned_user_ids_json:data.getAll('assigned').map(Number)},kind=data.get('item_type');
   const latest=await api('schedule');if(version!==panelVersion)return;
   if(availableScheduleSlots(latest.appointments||[],data.get('date'),Number(data.get('duration')),timing.assigned_user_ids_json).find(s=>s.hour===chosen.hour)?.busy)throw Error('This time is no longer available');
   if(kind==='Job')await api('jobs','POST',{client_id:Number(data.get('client_id')),title:name,visit:timing});
   else if(kind==='Request')await api('requests','POST',{client_id:Number(data.get('client_id')),title:name,assessment:{start_at:timing.scheduled_start,end_at:timing.scheduled_end,assigned_user_ids_json:timing.assigned_user_ids_json}});
   else await api('tasks','POST',{title:name,client_id:Number(data.get('client_id'))||null,due_date:data.get('date'),start_time:`${String(chosen.hour).padStart(2,'0')}:00`,end_time:`${String(chosen.end.getHours()).padStart(2,'0')}:${String(chosen.end.getMinutes()).padStart(2,'0')}`,assigned_user_id:timing.assigned_user_ids_json[0]||null,instructions:kind==='Event'?'Calendar event':''});
   if(version!==panelVersion)return;close();toast('Scheduled');await render();
 }catch(err){if(version===panelVersion)error(err);}};
}
